using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Web.Script.Serialization;
namespace ClearSpace {
public static class SoftwareUpdateTests {
 public static void Verify(string directory,Action<bool,string> check){
  string root=Path.Combine(directory,"software-update-fixtures");Directory.CreateDirectory(root);Func<Action,bool> rejects=action=>{try{action();return false;}catch{return true;}};
  check(new SoftwareRelease{Version="beta0.20",Build=2}.IsNewer("beta0.20",1),"An internal build update is detected within the same beta release");check(!new SoftwareRelease{Version="beta0.20",Build=1}.IsNewer("beta0.20",2),"Update checks reject older internal builds");check(new SoftwareRelease{Version="beta0.21",Build=1}.IsNewer("beta0.20",9),"A new beta release outranks the preceding internal build series");check(rejects(()=>SoftwareUpdates.VersionNumber("beta0.20/../evil")),"Release names cannot inject paths");
  check(!SoftwareUpdates.TrustedDownload(new Uri("http://github.com/CrazyHandin/Clarity"))&&!SoftwareUpdates.TrustedDownload(new Uri("https://github.com.attacker.invalid/a"))&&!SoftwareUpdates.TrustedDownload(new Uri("https://user@github.com/a")),"Software downloads reject HTTP, lookalike hosts, and embedded credentials");
  using(var stop=new System.Threading.CancellationTokenSource()){stop.Cancel();var cancelled=new SoftwareAsset{Name="cancelled.zip",Url=SoftwareUpdates.AssetUrl("beta0.20","cancelled.zip"),SHA256=new string('a',64),Size=10};check(rejects(()=>SoftwareUpdates.Download(cancelled,root,stop.Token,null))&&!File.Exists(Path.Combine(root,"cancelled.zip")),"Cancelling before download makes no network request and removes its partial file");}
  var published=new List<Dictionary<string,object>>();var artifacts=new List<Dictionary<string,object>>();foreach(string suffix in new[]{"-setup.exe","-portable.zip"}){string name="Clarity-beta0.20-build2"+suffix,hash=new string('a',64);published.Add(new Dictionary<string,object>{{"name",name},{"size",10L},{"digest","sha256:"+hash},{"browser_download_url",SoftwareUpdates.AssetUrl("beta0.20",name)}});artifacts.Add(new Dictionary<string,object>{{"Name",name},{"Size",10L},{"SHA256",hash}});}
  var manifest=new Dictionary<string,object>{{"Schema",1},{"Version","beta0.20"},{"Build",2},{"Artifacts",artifacts}};var json=new JavaScriptSerializer();check(SoftwareUpdates.ParseManifest(json.Serialize(manifest),"beta0.20",published,"").Assets.Count==2,"A build manifest must match both published GitHub package records");published[0]["digest"]="sha256:"+new string('b',64);check(rejects(()=>SoftwareUpdates.ParseManifest(json.Serialize(manifest),"beta0.20",published,"")),"A package hash mismatch prevents update selection");published[0]["digest"]="sha256:"+new string('a',64);published[0]["browser_download_url"]="https://example.invalid/payload.exe";check(rejects(()=>SoftwareUpdates.ParseManifest(json.Serialize(manifest),"beta0.20",published,"")),"Manifest downloads stay within the configured repository");
  manifest["Highlights"]=new Dictionary<string,object>{{"zh-CN","Fixture summary"},{"en","Fixture summary"}};int requests=0;var direct=SoftwareUpdates.Check(System.Threading.CancellationToken.None,(url,limit,token)=>{requests++;if(url!=SoftwareUpdates.LatestManifestUrl||url.Contains("api.github.com")||limit!=65536)throw new IOException("Unexpected API dependency");return json.Serialize(manifest);});check(requests==1&&direct.Build==2&&direct.Notes=="Fixture summary"&&direct.Assets.All(a=>a.Url.StartsWith("https://github.com/CrazyHandin/Clarity/releases/download/")),"Update checks use one official HTTPS manifest request without depending on anonymous API limits");
  artifacts[0]["SHA256"]="invalid";check(rejects(()=>SoftwareUpdates.ParseDownloadManifest(json.Serialize(manifest))),"Direct manifest checks still reject malformed package checksums");artifacts[0]["SHA256"]=new string('a',64);artifacts[0]["Name"]="../Clarity.exe";check(rejects(()=>SoftwareUpdates.ParseDownloadManifest(json.Serialize(manifest))),"Direct update manifests cannot redirect packages through arbitrary paths");artifacts[0]["Name"]="Clarity-beta0.20-build2-setup.exe";
  foreach(string name in new[]{"../outside.txt","/Clarity.exe","docs/../Clarity.exe","docs\\TERMS.txt","Logs/history.json","personal.txt"})check(rejects(()=>UpdatePackage.Destination(root,name)),"Portable update path is rejected: "+name);
  string zip=Path.Combine(root,"valid.zip");using(var archive=ZipFile.Open(zip,ZipArchiveMode.Create)){foreach(string name in new[]{"Clarity.exe","Clarity.exe.config","README.md"})using(var writer=new StreamWriter(archive.CreateEntry(name).Open()))writer.Write("new "+name);}string payload=Path.Combine(root,"payload");var files=UpdatePackage.Extract(zip,SoftwareUpdates.HashFile(zip),payload);check(files.Count==3,"A verified archive expands only its approved program files");check(rejects(()=>UpdatePackage.Extract(zip,new string('0',64),Path.Combine(root,"bad-hash"))),"Portable application rejects an archive modified after downloading");
  string target=Path.Combine(root,"target");Directory.CreateDirectory(target);File.WriteAllText(Path.Combine(target,"Clarity.exe"),"old program");File.WriteAllText(Path.Combine(target,"README.md"),"old readme");Directory.CreateDirectory(Path.Combine(target,"Logs"));File.WriteAllText(Path.Combine(target,"Logs","keep.json"),"personal audit fixture");
  check(rejects(()=>UpdatePackage.Apply(target,payload,files,index=>{if(index==1)throw new IOException("injected update failure");})),"An interrupted program replacement reports failure");check(File.ReadAllText(Path.Combine(target,"Clarity.exe"))=="old program"&&!File.Exists(Path.Combine(target,"Clarity.exe.config")),"Failed portable replacement rolls back the original executable and new files");UpdatePackage.Apply(target,payload,files);check(File.ReadAllText(Path.Combine(target,"Clarity.exe"))=="new Clarity.exe"&&File.ReadAllText(Path.Combine(target,"README.md"))=="new README.md","A complete portable transaction replaces its program payload");check(File.ReadAllText(Path.Combine(target,"Logs","keep.json"))=="personal audit fixture","Program updates preserve cleanup history and other unlisted user files");
  string escape=Path.Combine(root,"escape.zip");using(var archive=ZipFile.Open(escape,ZipArchiveMode.Create))using(var writer=new StreamWriter(archive.CreateEntry("../outside.txt").Open()))writer.Write("never extract");check(rejects(()=>UpdatePackage.Extract(escape,SoftwareUpdates.HashFile(escape),Path.Combine(root,"escape")))&&!File.Exists(Path.Combine(root,"outside.txt")),"Traversal inside a downloaded ZIP cannot write outside its extraction root");
  string badPlan=Path.Combine(root,"plan.dat");File.WriteAllText(badPlan,"not an update plan");check(UpdateLauncher.Apply(badPlan)==1&&!File.Exists(Path.Combine(root,"error.txt")),"An untrusted update task cannot write into an arbitrary directory");
  string previous=CleaningHistory.LastDirectory;try{string log=CleaningHistory.Save(new CleanResult{Deleted=1},Path.Combine(root,"portable-app"));check(File.Exists(log)&&Path.GetDirectoryName(log)==Path.Combine(root,"portable-app","Logs"),"Cleanup history automatically saves underneath the program directory");}finally{CleaningHistory.LastDirectory=previous;}
 }
}
}
